<?php
$base = 'plugin/inventory-partners/';
$currencyDisplay = $currencyDisplay ?? 'toman';
$money = static function ($rial) use ($currencyDisplay) {
    return $currencyDisplay === 'rial'
        ? \Proma\Plugins\PartnershipLedger\Domain\Money::formatInteger((string) ($rial ?? '0')) . ' ریال'
        : \Proma\Plugins\PartnershipLedger\Domain\Money::formatToman((string) ($rial ?? '0'));
};
$statusLabels = [
    'active' => 'فعال', 'archived' => 'بایگانی', 'posted' => 'ثبت قطعی', 'pending' => 'در انتظار دریافت',
    'pending_approval' => 'در انتظار تأیید', 'approved' => 'تأییدشده', 'paid' => 'پرداخت‌شده',
    'rejected' => 'ردشده', 'returned' => 'برگشت‌خورده', 'cancelled' => 'لغوشده', 'refunded' => 'مرجوع‌شده',
    'cash' => 'نقدی', 'installment' => 'اقساطی', 'quantity' => 'تعدادی', 'serial' => 'سریالی',
    'mobile' => 'موبایل', 'tablet' => 'تبلت', 'digital' => 'کالای دیجیتال', 'accessory' => 'لوازم جانبی', 'other' => 'سایر',
];
$statusClass = static function ($status) {
    if (in_array((string) $status, ['active', 'posted', 'approved', 'paid'], true)) { return 'is-success'; }
    if (in_array((string) $status, ['pending', 'pending_approval'], true)) { return 'is-warning'; }
    if (in_array((string) $status, ['rejected', 'cancelled', 'returned', 'refunded', 'archived'], true)) { return 'is-danger'; }
    return '';
};
$formatDate = static function ($value) {
    return function_exists('jdatetime') ? jdatetime($value ?? '') : (string) ($value ?? '—');
};
$partners = $partners ?? [];
$products = $products ?? [];
$warehouses = $warehouses ?? [];
$lots = $lots ?? [];
$nonce = $nonce ?? bin2hex(random_bytes(10));
$can = $can ?? static function () { return false; };
$canCosts = $canCosts ?? false;
