    ['settings', 'تنظیمات', 'manage_settings'],
];
$key = static function ($prefix) use ($nonce) { return $prefix . '-' . $nonce . '-' . bin2hex(random_bytes(4)); };
$shareFields = static function (array $partners, $prefix) {
    if (!$partners) {
        echo '<p class="pip-muted">برای ثبت خرید یا تعدیل ورودی، ابتدا شریک فعال تعریف کنید.</p>';
        return;
    }
    echo '<div class="pip-share-grid"><div class="pip-share-head"><strong>شریک</strong><strong>سهم سرمایه ٪</strong><strong>سهم سود ٪</strong></div>';
    foreach ($partners as $partner) {
        $id = (int) $partner['id'];
        $capital = isset($partner['default_capital_share_bp']) ? number_format(((int) $partner['default_capital_share_bp']) / 100, 2, '.', '') : '';
        $profit = isset($partner['default_profit_share_bp']) ? number_format(((int) $partner['default_profit_share_bp']) / 100, 2, '.', '') : '';
        echo '<div class="pip-share-row"><span>' . e($partner['full_name']) . '</span>';
        echo '<label class="pip-visually-hidden" for="' . e($prefix . '-capital-' . $id) . '">سهم سرمایه ' . e($partner['full_name']) . '</label>';
        echo '<input id="' . e($prefix . '-capital-' . $id) . '" type="text" inputmode="decimal" name="capital_shares[' . $id . ']" value="' . e($capital) . '" min="0" max="100" step="0.01" inputmode="decimal" placeholder="۰">';
        echo '<label class="pip-visually-hidden" for="' . e($prefix . '-profit-' . $id) . '">سهم سود ' . e($partner['full_name']) . '</label>';
        echo '<input id="' . e($prefix . '-profit-' . $id) . '" type="text" inputmode="decimal" name="profit_shares[' . $id . ']" value="' . e($profit) . '" min="0" max="100" step="0.01" inputmode="decimal" placeholder="۰"></div>';
    }
    echo '</div><small class="pip-help">جمع سهم سرمایه و جمع سهم سود هرکدام باید دقیقاً ۱۰۰٪ باشد. این سهم در سند همان محموله ثبت می‌شود.</small>';
};
$expenseShareFields = static function (array $partners, $prefix) {
    if (!$partners) {
        echo '<p class="pip-muted">برای تخصیص هزینه ابتدا شریک فعال تعریف کنید.</p>';
        return;
    }
    echo '<div class="pip-share-grid pip-expense-share-grid"><div class="pip-share-head"><strong>شریک</strong><strong>سهم هزینه ٪</strong></div>';
    foreach ($partners as $partner) {
        $id = (int) $partner['id'];
        $share = isset($partner['default_profit_share_bp']) ? number_format(((int) $partner['default_profit_share_bp']) / 100, 2, '.', '') : '';
        echo '<div class="pip-share-row"><span>' . e($partner['full_name']) . '</span><label class="pip-visually-hidden" for="' . e($prefix . '-expense-' . $id) . '">سهم هزینه ' . e($partner['full_name']) . '</label>';
        echo '<input id="' . e($prefix . '-expense-' . $id) . '" type="text" inputmode="decimal" name="expense_shares[' . $id . ']" value="' . e($share) . '" min="0" max="100" step="0.01" placeholder="۰"></div>';
    }
    echo '</div><small class="pip-help">پیش‌فرض، سهم سود فعلی شرکاست. جمع سهم‌های واردشده باید دقیقاً ۱۰۰٪ باشد؛ مقادیر این هزینه در سند آن ثابت می‌مانند.</small>';
};
$lookupPicker = static function ($kind, $field, $endpoint, $placeholder, $required = false) {
    $requiredAttr = $required ? ' required' : '';
    echo '<div class="pip-picker" data-pip-picker="' . e($kind) . '" data-endpoint="' . e(url($endpoint)) . '">';
    echo '<input type="search" autocomplete="off" data-pip-picker-input placeholder="' . e($placeholder) . '" aria-autocomplete="list" aria-expanded="false"' . $requiredAttr . '>';
    echo '<input type="hidden" name="' . e($field) . '" data-pip-picker-value>';
    echo '<div class="pip-picker-results" data-pip-picker-results role="listbox" hidden></div><small class="pip-picker-selected" data-pip-picker-selected hidden></small></div>';
};
$warehouseOptions = static function (array $warehouses) {
    foreach ($warehouses as $warehouse) {
        echo '<option value="' . (int) $warehouse['id'] . '">' . e($warehouse['name']) . '</option>';
    }
};
